"""<line> ::= <color> contain <contents>"""
def parse_line(line: Any) -> object {
    tokens = line.replace(",", " COMMA").replace(".", " PERIOD").split();
    tokens = `list(reversed(tokens));
    def eat(*expected: Any) -> object {
        assert (tokens.pop() in expected);
    }
    """<color> ::= <word> <word> (bag|bags)""";
    def parse_color() -> object {
        res = "{} {}".format(tokens.pop(), tokens.pop());
        eat("bag", "bags");
        return res;
    }
    """<contents> ::= contain (no other bags|<bag-amount-list>) PERIOD""";
    def parse_contents() -> object {
        assert (tokens.pop() == "contain");
        if (tokens[-1] == "no") {
            eat("no");
            eat("other");
            eat("bags");
            res = [(0, None)];
        } else {
            res = parse_bag_amount_list();
        }
        eat("PERIOD");
        return res;
    }
    """<bag-amount-list> ::= <integer> <color> (COMMA <integer> <color>)*""";
    def parse_bag_amount_list() -> object {
        res = [];
        am = int(tokens.pop());
        col = parse_color();
        res.append((am, col));
        while (tokens[-1] == "COMMA") {
            eat("COMMA");
            am = int(tokens.pop());
            col = parse_color();
            res.append((am, col));
        }
        return res;
    }
    col = parse_color();
    contents = parse_contents();
    assert not tokens;
    return (col, contents);
}

